insert into public.formula_chapters (id, subject_id, title, slug, sort_order)
values
  ('neet-biology-organisms-and-population', 'neet-biology', 'Organisms and Population', 'organisms-and-population', 33),
  ('neet-biology-ecosystem', 'neet-biology', 'Ecosystem', 'ecosystem', 34),
  ('neet-biology-biodiversity-and-conservation', 'neet-biology', 'Biodiversity and Conservation', 'biodiversity-and-conservation', 35)
on conflict (id) do update set
