insert into public.formula_cards (
  id, chapter_id, title, card_type, body, formulas, variables, conditions, table_data, diagram_data, diagram_svg, recall_data, importance, source_page, sort_order, is_active
)
values
  ('neet-biology-organisms-and-population-ecology-habitat-niche', 'neet-biology-organisms-and-population', 'Habitat and Niche', 'comparison', 'Ecology studies interactions among organisms and between organisms and the abiotic environment.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall","Examples/details"],"rows":[["Ecology","Study of interactions among organisms and between organism and physical environment","Organisms, Populations, Communities and Biomes"],["Habitat","Different habitats form due to regional and local variations within a biome","Rajasthan desert, rain-soaked Meghalaya forests, deep ocean trenches, thermal springs, compost pits and intestine microbes"],["Niche","Distinct role and position of an organism in its environment","Each organism tolerates conditions and uses resources"]]}'::jsonb, null, null, '{"recall_question":"What is niche?","reveal_answer":"Distinct role and position of an organism in its environment.","key_points":[],"examples":[],"neet_traps":["Habitat is place/context; niche is role and position."]}'::jsonb, 5, 135, 1, true),
  ('neet-biology-organisms-and-population-abiotic-factors', 'neet-biology-organisms-and-population', 'Major Abiotic Factors', 'classification', 'Temperature, water, light and soil shape organism distribution and survival.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Factor","Source-backed recall"],"rows":[["Temperature","Most ecologically relevant environmental factor; affects enzyme kinetics, basal metabolism and physiological functions"],["Water","Second most important factor; plant productivity and distribution depend on water"],["Light","Needed by plants for photosynthesis; photoperiod affects flowering, foraging, reproduction and migration"],["Soil","Composition, grain size, aggregation, pH, minerals and topography determine vegetation and animals"]]}'::jsonb, null, null, '{"recall_question":"Which abiotic factor is called most ecologically relevant?","reveal_answer":"Temperature.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 135, 2, true),
  ('neet-biology-organisms-and-population-thermal-salinity-tolerance', 'neet-biology-organisms-and-population', 'Tolerance Terms', 'comparison', 'The source classifies organisms by temperature and salinity tolerance ranges.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Pair","Wide tolerance","Narrow tolerance"],"rows":[["Temperature","Eurythermal","Stenothermal"],["Salinity","Euryhaline","Stenohaline"]]}'::jsonb, null, null, '{"recall_question":"Which organisms tolerate a wide range of salinities?","reveal_answer":"Euryhaline organisms.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 135, 3, true),
  ('neet-biology-organisms-and-population-regulator-conformer', 'neet-biology-organisms-and-population', 'Regulator vs Conformer', 'comparison', 'Regulators maintain homeostasis; conformers change with surroundings.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Regulator","Conformer"],"rows":[["Internal environment","Maintains stable internal environment by physiological and behavioural means","Body temperature or osmotic concentration changes with surroundings"],["Examples","All birds and mammals, very few lower vertebrates and invertebrates","99% animals and nearly all plants"],["Cost","Thermoregulation is energetically expensive, especially for small animals","Avoids the cost of maintaining constant internal environment"],["Graph cue","Internal level stays steady","Internal level follows external level"]]}'::jsonb, null, null, '{"recall_question":"Why are very small animals rare in Polar Regions?","reveal_answer":"They lose body heat very fast and must spend much energy to generate body heat.","key_points":[],"examples":[],"neet_traps":["Most animals are conformers, not regulators."]}'::jsonb, 5, 136, 4, true),
  ('neet-biology-organisms-and-population-migration-suspend', 'neet-biology-organisms-and-population', 'Migration vs Suspension', 'comparison', 'Organisms may escape stress temporarily or suspend activity through dormant forms.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Response","Source-backed recall","Examples"],"rows":[["Migrate","Move temporarily from stressful habitat to a hospitable area and return when stress is over","Migratory birds from Siberia at Keolado National Park, Bharatpur"],["Suspend in microbes/lower plants","Thick walled spores survive unfavourable conditions and germinate under suitable conditions","Bacteria, fungi and lower plants"],["Suspend in higher plants","Seeds and vegetative reproductive structures reduce metabolic activity during stress","Germinate under favourable moisture and temperature"],["Suspend in animals","Dormancy or slowed development","Hibernation, aestivation and diapause"]]}'::jsonb, null, null, '{"recall_question":"Which suspended-development stage is listed for zooplanktons?","reveal_answer":"Diapause.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 136, 5, true),
  ('neet-biology-organisms-and-population-hibernation-aestivation-diapause', 'neet-biology-organisms-and-population', 'Hibernation, Aestivation and Diapause', 'neet_trap', 'The suspension examples differ by season or developmental state.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed example"],"rows":[["Hibernation","Bears during winter"],["Aestivation","Some snails and fishes during summer"],["Diapause","Stage of suspended development of many zooplanktons in lakes and ponds"]]}'::jsonb, null, null, '{"recall_question":"Which term applies to summer dormancy in some snails and fishes?","reveal_answer":"Aestivation.","key_points":[],"examples":[],"neet_traps":["Hibernation is winter; aestivation is summer."]}'::jsonb, 5, 136, 6, true),
  ('neet-biology-organisms-and-population-adaptations', 'neet-biology-organisms-and-population', 'Adaptations', 'classification', 'Adaptation is a morphological, physiological or behavioural attribute enabling survival and reproduction.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Adaptation","Source-backed examples"],"rows":[["Kangaroo rat","Internal fat oxidation gives water; concentrated urine uses minimal water"],["Desert plants","Thick cuticle, sunken stomata, CAM pathway and Opuntia leaves reduced to spines"],["Allen''s Rule","Mammals from colder climates have shorter ears and limbs to reduce heat loss"],["Aquatic mammals","Seals have blubber below skin as insulator"],["High altitude","Acclimatization increases RBC and breathing rate and decreases haemoglobin binding capacity"],["Behavioural","Desert lizards bask in sun or move to shade; some species burrow into soil"]]}'::jsonb, null, null, '{"recall_question":"Which desert plant example has leaves reduced to spines?","reveal_answer":"Opuntia.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 136, 7, true),
  ('neet-biology-organisms-and-population-population-attributes', 'neet-biology-organisms-and-population', 'Population Attributes', 'comparison', 'Population density changes through births, deaths and movement.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Attribute","Source-backed recall","Effect on density"],"rows":[["Population","Group of individuals of same species in a geographical area, sharing or competing for resources and potentially reproducing","Base unit"],["Natality (B)","Number of births in a population during a given period","Increases"],["Mortality (D)","Number of deaths in a population during a given period","Decreases"],["Immigration (I)","Individuals of same species coming into habitat from elsewhere","Increases"],["Emigration (E)","Individuals leaving the habitat","Decreases"],["Sex ratio","Population has a sex ratio, e.g. 60% females and 40% males","Attribute"]]}'::jsonb, null, null, '{"recall_question":"Which two factors increase population density?","reveal_answer":"Natality and immigration.","key_points":[],"examples":[],"neet_traps":["Emigration decreases density; immigration increases it."]}'::jsonb, 5, 137, 8, true),
  ('neet-biology-organisms-and-population-age-pyramids', 'neet-biology-organisms-and-population', 'Age Pyramids', 'diagram', 'Age pyramids show population age distribution and growth status.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Pyramid","Source label"],"rows":[["Expanding","Growing"],["Stable","Stable"],["Declining","Declining"]]}'::jsonb, '{"type":"bio-age-pyramids"}'::jsonb, null, '{"recall_question":"Which age-pyramid status indicates a growing population?","reveal_answer":"Expanding.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 137, 9, true),
  ('neet-biology-organisms-and-population-population-growth-equations', 'neet-biology-organisms-and-population', 'Population Growth Equations', 'fact', 'The source gives exact symbols for density change and exponential growth.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Equation/value","Source-backed meaning"],"rows":[["Nt+1 = Nt + [(B + I) - (D + E)]","Population density at time t + 1"],["dN/dt = (b - d) x N","Increase or decrease in N during unit time"],["dN/dt = rN","When (b - d) = r"],["Nt = N0 ert","Integral form of exponential growth equation"],["e = 2.71828","Base of natural logarithms"]]}'::jsonb, null, null, '{"recall_question":"What does r represent in population growth?","reveal_answer":"Intrinsic rate of natural increase.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 137, 10, true),
  ('neet-biology-organisms-and-population-growth-models', 'neet-biology-organisms-and-population', 'Exponential vs Logistic Growth', 'diagram', 'Unlimited resources give a J-shaped curve; limited resources give a sigmoid curve.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Exponential growth","Logistic growth"],"rows":[["Resource condition","Unlimited resources","Limited resources"],["Curve","J-shaped curve","Sigmoid curve"],["Source name","Exponential or geometric fashion","Verhulst-Pearl Logistic Growth"],["Equation","dN/dt = rN","dN/dt = rN((K - N) / K)"],["K","Not used","Carrying capacity"]]}'::jsonb, '{"type":"bio-population-growth-curves"}'::jsonb, null, '{"recall_question":"Which growth curve occurs under unlimited resources?","reveal_answer":"Exponential growth, J-shaped curve.","key_points":[],"examples":[],"neet_traps":["K represents carrying capacity in logistic growth."]}'::jsonb, 5, 138, 11, true),
  ('neet-biology-organisms-and-population-r-values-life-history', 'neet-biology-organisms-and-population', 'r Values and Life History', 'fact', 'Life-history traits evolve under limited abiotic and biotic components of habitat.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed value/example"],"rows":[["Norway rat r","0.015"],["Flour beetle r","0.12"],["Human population in India (1981) r","0.0205"],["Breed once","Pacific salmon fish and bamboo"],["Breed many times","Most birds and mammals"],["Many small offspring","Oysters and pelagic fishes"],["Few large offspring","Birds and mammals"]]}'::jsonb, null, null, '{"recall_question":"What r value is given for human population in India (1981)?","reveal_answer":"0.0205.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 137, 12, true),
  ('neet-biology-organisms-and-population-interaction-matrix', 'neet-biology-organisms-and-population', 'Population Interaction Matrix', 'diagram', 'Interspecific interactions are represented with +, - and 0 effects.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Interaction","Species A","Species B","Source meaning"],"rows":[["Mutualism","+","+","Both species benefitted"],["Competition","-","-","Both species harmed"],["Predation","+","-","Predator benefitted; prey harmed"],["Parasitism","+","-","Parasite benefitted; host harmed"],["Commensalism","+","0","One benefitted; other unaffected"],["Amensalism","-","0","One harmed; other unaffected"]]}'::jsonb, '{"type":"bio-interaction-matrix"}'::jsonb, null, '{"recall_question":"Which interaction is + and 0?","reveal_answer":"Commensalism.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 138, 13, true),
  ('neet-biology-organisms-and-population-predation', 'neet-biology-organisms-and-population', 'Predation', 'concept', 'Predators control prey populations and maintain species diversity.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed examples"],"rows":[["Predator context","Carnivores and herbivores are predators in a broad ecological context"],["Phytophagous insects","About 25% insects"],["Prickly pear cactus","Introduced in Australia in 1920''s and later controlled by cactus-feeding predator moth"],["Pisaster","Removal caused extinction of over 10 invertebrate species within a year"],["Prey defenses","Camouflage, poisons, thorns and chemicals"],["Chemical defenses","Calotropis cardiac glycosides; nicotine, caffeine, quinine, strychnine and opium"]]}'::jsonb, null, null, '{"recall_question":"Which starfish example shows predators maintain diversity?","reveal_answer":"Pisaster.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 138, 14, true),
  ('neet-biology-organisms-and-population-competition', 'neet-biology-organisms-and-population', 'Competition', 'concept', 'Competition lowers fitness of one species in the presence of another.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Definition","Fitness of one species or r value is significantly lower in presence of another species"],["Unrelated competitors","Flamingoes and fishes compete for zooplankton in shallow South American lakes"],["Interference competition","Feeding efficiency reduced by inhibitory presence of another species even when resources are abundant"],["Abingdon tortoise","Extinct within a decade after goats were introduced in Galapagos Islands"],["Connell experiment","Removing Balanus allowed Chthamalus to colonize intertidal zone"],["Gause principle","Two closely related species competing for same resources cannot co-exist indefinitely in limited resources"],["Resource partitioning","Species divide limited resources by feeding times or foraging patterns"]]}'::jsonb, null, null, '{"recall_question":"What is competitive release?","reveal_answer":"Expansion of distributional range when competing species is removed.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 139, 15, true),
  ('neet-biology-organisms-and-population-parasitism', 'neet-biology-organisms-and-population', 'Parasitism', 'comparison', 'Parasites harm hosts and often show specialized adaptations.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type/cue","Source-backed recall","Examples"],"rows":[["Parasite adaptations","Loss of sense organs, adhesive organs or suckers, loss of digestive system and high reproductive capacity","Host-specific parasites co-evolve"],["Ectoparasites","Feed on external surface of host","Lice on humans, ticks on dogs, copepods on marine fishes, Cuscuta on hedge plants"],["Endoparasites","Live inside host body at sites such as liver, kidney, lungs and RBC","Life cycles are more complex"],["Brood parasitism","Parasitic birds lay eggs in host nest and let host incubate them","Cuckoo and crow"],["Female mosquito","Not considered parasite in source","Needs blood for reproduction, not as food"]]}'::jsonb, null, null, '{"recall_question":"Why is female mosquito not considered a parasite in the source?","reveal_answer":"It needs blood only for reproduction, not as food.","key_points":[],"examples":[],"neet_traps":["Cuscuta has no chlorophyll and derives nutrition from host."]}'::jsonb, 5, 139, 16, true),
  ('neet-biology-organisms-and-population-commensalism-mutualism', 'neet-biology-organisms-and-population', 'Commensalism vs Mutualism', 'comparison', 'Commensalism benefits one without affecting the other; mutualism benefits both.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Interaction","Source-backed examples"],"rows":[["Commensalism","Orchid on mango branch; barnacles on whale; cattle egret with grazing cattle; clown fish with sea anemone"],["Mutualism","Lichen between fungus and algae/cyanobacteria; mycorrhizae between fungi and higher plant roots"],["Fig and wasp","Fig species pollinated only by partner wasp; fig offers developing seeds as larval food"],["Ophrys sexual deceit","Petal resembles female bee; male bee pseudocopulates and transfers pollen"]]}'::jsonb, null, null, '{"recall_question":"Which interaction is shown by lichen?","reveal_answer":"Mutualism.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 139, 17, true),
  ('neet-biology-ecosystem-ecosystem-basics', 'neet-biology-ecosystem', 'Ecosystem Structure', 'classification', 'An ecosystem is a functional unit where organisms interact with each other and the physical environment.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Component","Source-backed recall"],"rows":[["Terrestrial ecosystems","Forest, grassland and desert"],["Aquatic ecosystems","Pond, lake, wetland, river and estuary"],["Man-made ecosystems","Crop fields and aquarium"],["Global ecosystem","Entire biosphere"],["Stratification","Vertical distribution of species at different levels; trees, shrubs, herbs and grasses in forest"]]}'::jsonb, null, null, '{"recall_question":"What is stratification in an ecosystem?","reveal_answer":"Vertical distribution of different species occupying different levels.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 140, 1, true),
  ('neet-biology-ecosystem-pond-ecosystem', 'neet-biology-ecosystem', 'Pond as Ecosystem', 'concept', 'A pond is a shallow, simple, self-sustainable water body with all basic ecosystem components.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Component/function","Source-backed examples"],"rows":[["Abiotic components","Water and soil deposit"],["Climatic conditions","Solar input, temperature cycle and day-length"],["Autotrophs","Phytoplankton, some algae and floating, submerged and marginal plants"],["Consumers","Zooplankton, free swimming and bottom dwelling forms"],["Decomposers","Fungi, bacteria and flagellates"],["Four functions","Productivity, decomposition, energy flow and nutrient cycling"]]}'::jsonb, null, null, '{"recall_question":"What are the four basic ecosystem functions?","reveal_answer":"Productivity, decomposition, energy flow and nutrient cycling.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 140, 2, true),
  ('neet-biology-ecosystem-productivity', 'neet-biology-ecosystem', 'GPP vs NPP', 'comparison', 'Primary productivity is biomass production by plants during photosynthesis.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall"],"rows":[["Primary production","Biomass produced per unit area over time by plants during photosynthesis"],["Productivity","Rate of biomass production"],["GPP","Rate of production of organic matter during photosynthesis"],["NPP","Available biomass for consumption to heterotrophs"],["Equation","NPP = GPP - R"],["Secondary productivity","Rate of formation of new organic matter by consumers"]]}'::jsonb, null, null, '{"recall_question":"What is the source equation for NPP?","reveal_answer":"NPP = GPP - R.","key_points":[],"examples":[],"neet_traps":["GPP includes plant respiration losses; NPP is available biomass."]}'::jsonb, 5, 140, 3, true),
  ('neet-biology-ecosystem-productivity-values', 'neet-biology-ecosystem', 'Productivity Values', 'fact', 'The source gives whole-biosphere and ocean NPP values.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed value"],"rows":[["Annual NPP of whole biosphere","About 170 billion tons dry weight of organic matter"],["Ocean surface share","About 70% of surface"],["Ocean productivity","Only 55 billion tons"],["Primary production units","Weight (g-2) or energy (kcal m-2)"],["Productivity units","g-2 yr-1 or (kcal m-2) yr-1"]]}'::jsonb, null, null, '{"recall_question":"What annual NPP value is given for the whole biosphere?","reveal_answer":"About 170 billion tons dry weight.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 140, 4, true),
  ('neet-biology-ecosystem-decomposition-process', 'neet-biology-ecosystem', 'Decomposition Process', 'process', 'Decomposition breaks complex organic matter into inorganic substances.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["Fragmentation","Detritivores such as earthworm break detritus into smaller particles"],["Leaching","Water soluble inorganic nutrients go into soil horizon and precipitate as unavailable salts"],["Catabolism","Bacterial and fungal enzymes degrade detritus into simpler inorganic substances"],["Humification","Humus accumulates; resistant to microbial action and serves as nutrient reservoir"],["Mineralization","Microbes degrade humus and release inorganic nutrients"]]}'::jsonb, '{"type":"bio-decomposition-flow"}'::jsonb, null, '{"recall_question":"What is raw material for decomposition called?","reveal_answer":"Detritus.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 140, 5, true),
  ('neet-biology-ecosystem-decomposition-factors', 'neet-biology-ecosystem', 'Factors Affecting Decomposition', 'comparison', 'Detritus chemistry and climate control decomposition rate.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Factor","Slower","Faster"],"rows":[["Chemical composition","Lignin and chitin rich detritus","Nitrogen and water-soluble substances like sugars"],["Climate","Low temperature and anaerobiosis inhibit decomposition","Warm and moist environment favours decomposition"]]}'::jsonb, null, null, '{"recall_question":"Which detritus chemistry slows decomposition?","reveal_answer":"Rich in lignin and chitin.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 140, 6, true),
  ('neet-biology-ecosystem-energy-flow', 'neet-biology-ecosystem', 'Energy Flow', 'process', 'Energy decreases at successive trophic levels, and the number of GFC trophic levels is restricted by 10% law.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Energy source","Sun is the only source for all ecosystems except deep sea hydro-thermal ecosystem"],["PAR","Less than 50% of incident solar radiation is photosynthetically active radiation"],["Plant capture","Plants capture only 2-10% of PAR"],["10% law","Only 10% energy is transferred to each trophic level from the lower trophic level"],["Standing crop","Amount of living material in a trophic level at a given time"]]}'::jsonb, '{"type":"bio-trophic-energy"}'::jsonb, null, '{"recall_question":"What percentage of energy is transferred between trophic levels according to 10% law?","reveal_answer":"Only 10%.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 141, 7, true),
  ('neet-biology-ecosystem-food-chain-types', 'neet-biology-ecosystem', 'Grazing vs Detritus Food Chain', 'comparison', 'The source distinguishes food chains by whether feeding begins with living plants or detritus.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Grazing Food Chain (GFC)","Detritus Food Chain (DFC)"],"rows":[["Beginning","Primary consumer feeds on living plants","Primary consumer feeds on dead organic matter"],["Aquatic ecosystem","Major conduit for energy flow","Less emphasized"],["Terrestrial ecosystem","Less energy than DFC","Much energy flows through DFC"],["Connections","May connect with DFC at some levels","Some DFC organisms are prey to GFC animals"],["Food web","Interconnections of food chains","Interconnections of food chains"]]}'::jsonb, null, null, '{"recall_question":"Which food chain is major energy conduit in aquatic ecosystems?","reveal_answer":"Grazing Food Chain.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 141, 8, true),
  ('neet-biology-ecosystem-ecological-pyramids', 'neet-biology-ecosystem', 'Ecological Pyramids', 'diagram', 'Ecological pyramids represent food chains as number, biomass or energy pyramids.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Pyramid","Source-backed recall","Exception/trap"],"rows":[["Number","Grassland example upright","Inverted when insects feed on a tree"],["Biomass","Shows sharp decrease in biomass at higher trophic levels","In sea, inverted because fish biomass exceeds phytoplankton biomass"],["Energy","Primary producers convert only 1% of sunlight available to them into NPP","Always upright because energy is lost as heat at each trophic level"]]}'::jsonb, '{"type":"bio-ecological-pyramids"}'::jsonb, null, '{"recall_question":"Which ecological pyramid is always upright?","reveal_answer":"Pyramid of energy.","key_points":[],"examples":[],"neet_traps":["Number and biomass can be inverted; energy is always upright."]}'::jsonb, 5, 141, 9, true),
  ('neet-biology-ecosystem-pyramid-limitations', 'neet-biology-ecosystem', 'Ecological Pyramid Limitations', 'neet_trap', 'Pyramids simplify food chains and miss several real ecosystem features.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Limitation","Source-backed detail"],"rows":[["Same species","Does not consider same species belonging to two or more trophic levels"],["Food web","Assumes a simple food chain that never exists in nature and does not accommodate food web"],["Saprophytes","Saprophytes are not included"]]}'::jsonb, null, null, '{"recall_question":"Are saprophytes included in ecological pyramids in the source?","reveal_answer":"No.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 142, 10, true),
  ('neet-biology-ecosystem-succession-basics', 'neet-biology-ecosystem', 'Ecological Succession', 'concept', 'Succession is gradual, slow and predictable change toward a climax community.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall"],"rows":[["Succession","Change in species composition of an area leading to a climax community"],["Climax community","Community in equilibrium with environment"],["Sere","Entire sequence of communities that successively change in an area"],["Seral stage","Individual transitional community"],["Pioneer species","Species invading a bare area"],["During succession","Species diversity, number of species/organisms and total biomass increase"]]}'::jsonb, null, null, '{"recall_question":"What are species invading a bare area called?","reveal_answer":"Pioneer species.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 142, 11, true),
  ('neet-biology-ecosystem-primary-secondary-succession', 'neet-biology-ecosystem', 'Primary vs Secondary Succession', 'comparison', 'Primary succession begins where no living organisms existed; secondary follows loss of existing organisms.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Primary succession","Secondary succession"],"rows":[["Starting area","No living organisms ever existed","Existing organisms are lost"],["Examples","Newly cooled lava, bare rock, newly created pond or reservoir","Abandoned farm lands, burned or cut forests, flooded lands"],["Soil/sediment","Fertile soil must be formed","Some soil or sediment is present"],["Speed","Very slow","Faster than primary succession"]]}'::jsonb, null, null, '{"recall_question":"Which succession is faster in the source?","reveal_answer":"Secondary succession.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 142, 12, true),
  ('neet-biology-ecosystem-hydrarch-xerarch', 'neet-biology-ecosystem', 'Hydrarch vs Xerarch Succession', 'comparison', 'Both plant succession paths lead toward mesic conditions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Starting condition","Direction"],"rows":[["Hydrarch succession","Wetter areas","Hydric to mesic conditions"],["Xerarch succession","Dry areas","Xeric to mesic conditions"]]}'::jsonb, null, null, '{"recall_question":"Which succession progresses from xeric to mesic conditions?","reveal_answer":"Xerarch succession.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 142, 13, true),
