  ('neet-biology-ecosystem-carbon-phosphorus', 'neet-biology-ecosystem', 'Carbon vs Phosphorus Cycle', 'comparison', 'The source contrasts carbon and phosphorus by atmospheric input and gaseous exchange.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Carbon cycle","Phosphorus cycle"],"rows":[["Reservoir","Atmosphere about 1%, organisms 49% dry weight, oceans 71% dissolved carbon, fossil fuel etc.","Rock in the form of phosphates"],["Annual fixation","4 x 10^13 kg carbon fixed in biosphere through photosynthesis annually","No annual fixation value given"],["Atmospheric input","Higher","Much smaller"],["Gaseous exchange","There is gaseous exchange between organism and environment","Gaseous exchange is negligible"]]}'::jsonb, null, null, '{"recall_question":"What is the natural reservoir of phosphorus?","reveal_answer":"Rock in the form of phosphates.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 143, 16, true),
  ('neet-biology-ecosystem-ecosystem-services', 'neet-biology-ecosystem', 'Ecosystem Services', 'fact', 'Ecosystem services are products of ecosystem processes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Forest services","Purify air and water, mitigate droughts and floods, cycle nutrients, generate fertile soils, provide wildlife habitat, maintain biodiversity, pollinate crops and store carbon"],["Robert Costanza","Tried to put price tags on nature''s life-support services"],["Total value","US $ 33 trillion a year"],["Global GNP comparison","Nearly twice global gross national product, US $ 18 trillion"],["Soil formation","About 50% of total cost"],["Climate regulation and wildlife habitat","About 6% each"]]}'::jsonb, null, null, '{"recall_question":"What average annual value is given for ecosystem services?","reveal_answer":"US $ 33 trillion a year.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 143, 17, true),
