  ('neet-biology-biodiversity-and-conservation-latitudinal-gradient', 'neet-biology-biodiversity-and-conservation', 'Latitudinal Gradient', 'comparison', 'Species diversity decreases from equator to poles.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Region","Source-backed value/detail"],"rows":[["Tropics","23.5° N to 23.5° S; more species than temperate or polar areas"],["Colombia","About 1400 bird species"],["India","> 1200 bird species"],["New York (41° N)","105 bird species"],["Greenland (71° N)","56 bird species"],["Ecuador","Up to 10 times vascular plant species compared to Midwest USA temperate forest"]]}'::jsonb, null, null, '{"recall_question":"How does species diversity change from equator to poles?","reveal_answer":"It decreases from the equator to the poles.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 144, 3, true),
  ('neet-biology-biodiversity-and-conservation-amazon-biodiversity', 'neet-biology-biodiversity-and-conservation', 'Amazonian Rain Forest Diversity', 'fact', 'The source calls tropical Amazonian rain forest the greatest biodiversity on earth.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Group","Source-backed count"],"rows":[["Plants","> 40000 species"],["Fishes","3000 species"],["Birds","1300 species"],["Mammals","427 species"],["Amphibians","427 species"],["Reptiles","378 species"],["Invertebrates","> 1,25,000 species"]]}'::jsonb, null, null, '{"recall_question":"Which rainforest is called greatest biodiversity on earth?","reveal_answer":"Tropical Amazonian rain forest.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 144, 4, true),
  ('neet-biology-biodiversity-and-conservation-species-area', 'neet-biology-biodiversity-and-conservation', 'Species-Area Relationship', 'diagram', 'Alexander von Humboldt found species richness increases with explored area up to a limit.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Equation/value","Source-backed meaning"],"rows":[["S = CA^Z","Species richness-area relationship"],["S","Species richness"],["A","Area"],["C","Y-intercept"],["Z","Slope of the line or regression coefficient"],["Log S = log C + Z log A","Straight line on logarithmic scale"],["Small areas Z","0.1 to 0.2"],["Large areas Z","0.6 to 1.2"],["Frugivorous birds and mammals Z","1.15"]]}'::jsonb, '{"type":"bio-species-area"}'::jsonb, null, '{"recall_question":"What does Z represent in species-area relationship?","reveal_answer":"Slope of the line, or regression coefficient.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 144, 5, true),
